import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/yfr4')
from lib import *
FVG="Portions de fruits et légumes"
def fv(n): return f"{FVG}§{FVG} par portion : {n}"
FRZ="Instructions de congélation : "
recs=[
R(7844829,"Brochettes d'agneau épicées","Relevez votre dîner avec ces délicieuses brochettes d'agneau, où la viande tendre et les légumes croquants s'associent pour un plat vraiment spectaculaire. Cette recette a été sélectionnée en partenariat avec Slimming World.","4","621 g",
["750 g de pommes de terre farineuses, comme la King Edward ou la Maris Piper, coupées en gros frites","Spray de cuisson basses calories","2 c. à café de cumin moulu","2 c. à café de paprika doux fumé","2 c. à café d'origan séché","Zeste râpé et jus d'1 citron non traité","2 épaisses tranches (360 g) de gigot d'agneau maigre, graisse visible retirée, coupées en morceaux","2 oignons rouges moyens, coupés en quartiers","2 gros poivrons (de n'importe quelle couleur), épépinés et coupés en morceaux","Quartiers de citron, pour servir","Grande salade mélangée, pour servir","Quelques feuilles de menthe fraîche, pour servir"],
["Préchauffez le four à 200 °C (chaleur tournante 180 °C, th. 6).","Mélangez le cumin, le paprika, l'origan, le zeste et le jus de citron dans un plat peu profond. Ajoutez l'agneau, remuez pour bien l'enrober, puis couvrez et laissez reposer au réfrigérateur au moins 1 heure, ou toute la nuit si possible.","Mettez les frites dans une casserole d'eau bouillante sur feu vif et faites cuire 5 minutes. Égouttez bien, remettez dans la casserole et couvrez. Laissez refroidir légèrement, puis secouez la casserole pour rendre les bords rugueux.","Chemisez une plaque de cuisson de papier sulfurisé antiadhésif et disposez les frites dessus en une seule couche. Saupoudrez de poivre noir fraîchement moulu et d'un peu de paprika fumé, vaporisez quelques pressions de spray de cuisson basses calories et faites cuire 25 minutes, ou jusqu'à ce qu'elles soient dorées.","Préchauffez votre gril à puissance moyenne-élevée. Enfilez l'agneau, les oignons et les poivrons sur 4 brochettes en métal et faites griller 10 à 12 minutes en les retournant de temps en temps, jusqu'à ce qu'ils soient bien cuits. (Vous pouvez aussi les cuire dans une poêle à griller antiadhésive ou au barbecue pendant à peu près le même temps.)","Servez chaud, avec les quartiers de citron, la salade et les frites, et parsemez de menthe."],
["Veillez à ce que l'agneau soit cuit à cœur et respectez les règles de sécurité alimentaire.",fv(3)]),
R(7845092,"Salade de poulet grillé, sauce à l'avocat","Cette salade super savoureuse est un excellent déjeuner sain.","2","402 g",
["2 blancs de poulet (150 g chacun)","2 c. à soupe de yaourt grec","1 c. à soupe de yaourt nature","2 c. à soupe de jus de citron","1 c. à soupe de thym frais","100 g de radis blanc (daïkon) ou de radis, finement émincés","10 cm de concombre, épépiné et émincé","4 oignons nouveaux, très finement émincés","75 g de germes de soja","1 barquette de cresson alénois","1/2 avocat","1 c. à soupe de vinaigre de vin de riz","1 c. à soupe d'huile de sésame","1 c. à soupe de coriandre hachée","1 c. à soupe de graines de sésame grillées"],
["Placez les blancs de poulet entre deux feuilles de film alimentaire et aplatissez-les avec un rouleau à pâtisserie jusqu'à 1 cm d'épaisseur. Mélangez le yaourt, le citron et le thym et poivrez.","Mettez le poulet et la marinade dans un bol et laissez reposer 15 minutes.","Pendant ce temps, mettez le radis blanc, le concombre, les oignons, les germes de soja et le cresson dans un grand saladier et mélangez.","Mettez l'avocat, le vinaigre, l'huile, la coriandre et le yaourt dans un blender et mixez jusqu'à obtenir une texture lisse. Faites cuire le poulet au barbecue, dans une poêle-gril ou sous le gril pendant environ 8 minutes, en le retournant une fois, jusqu'à ce qu'il soit cuit à cœur. Vérifiez qu'aucune chair rose n'est visible et que le jus s'écoule clair lorsque vous piquez la partie la plus épaisse du poulet.","Arrosez la salade de sauce, parsemez de graines de sésame, ajoutez le poulet émincé dessus et servez."],
[fv(2)]),
R(7848709,"Crêpes","Ces crêpes sans gluten sont délicieuses garnies de préparations sucrées ou salées.","6","93 g",
["100 g de riz moulu","25 g de fécule de maïs","2 œufs, battus","300 ml de lait demi-écrémé","un peu d'huile pour la cuisson"],
["Battez ensemble tous les ingrédients dans un saladier.","Chauffez une poêle antiadhésive moyenne et badigeonnez-la d'un peu d'huile.","Remuez la pâte avant d'en verser une louche dans la poêle, puis inclinez la poêle pour que la pâte recouvre le fond. Faites cuire 1 à 2 minutes de chaque côté, jusqu'à ce que la crêpe soit dorée.","Répétez jusqu'à épuisement de la pâte (remuez-la à chaque fois avant de la verser dans la poêle). Faites glisser les crêpes sur une assiette et servez avec des fruits."],
["Pour garder les crêpes au chaud, posez une assiette sur une casserole d'eau frémissante et empilez-y les crêpes au fur et à mesure.","Ces crêpes sont aussi délicieuses avec des garnitures salées. Essayez avec des poireaux et des champignons nappés d'une sauce au fromage, ou avec de la ratatouille.",FRZ+"congelez en portions emballées individuellement, avec du papier sulfurisé entre chaque crêpe. Décongelez 1 heure, ou au micro-ondes.",fv(0)]),
R(7854676,"Houmous à la betterave","Ce houmous éclatant est plus pauvre en matières grasses que les recettes traditionnelles et fait un plat de fête merveilleusement coloré.","8","79 g",
["1 boîte de 400 g de pois chiches, égouttés et rincés","1 paquet de 300 g de betteraves cuites au naturel (dans leur jus/eau), égouttées","1 gousse d'ail, écrasée","1 pincée de piment de Cayenne","1 c. à café de cumin","poivre noir fraîchement moulu","2 c. à café de tahini","3 c. à soupe de yaourt nature","jus d'un demi-citron","1 c. à café de menthe hachée pour servir","crudités de légumes, pour servir"],
["Mixez la moitié de la boîte de pois chiches avec tous les autres ingrédients jusqu'à obtenir une texture presque lisse et un mélange homogène.","Écrasez grossièrement le reste des pois chiches à la fourchette et incorporez-les à la préparation : cela donne de la texture à votre houmous. Parsemez de menthe et servez avec des crudités."],
["Le dip de fête parfait : disposez-le dans un bol entouré de bâtonnets de carotte, de poivron, de concombre et de céleri et de lanières de pain pita.","Servez avec du pain pita chaud, ainsi que des légumes ou de la salade, pour une collation plus consistante.",fv(0)]),
R(7854824,"Chili aux légumes","Économique et facile à préparer, ce plat polyvalent peut être servi avec du riz ou des patates douces au four, en wrap avec une salade, ou transformé en enchiladas, tacos ou nachos.","8","195 g",
["2 c. à café d'huile de colza","2 à 3 oignons, finement hachés","1 poivron rouge, finement haché","150 g de carottes, finement hachées","1 courgette, finement hachée","100 g de champignons, finement hachés","1 à 2 c. à café de piment en poudre (doux ou fort, selon votre goût)","1 c. à café de cumin moulu","1 c. à café d'origan","1 boîte de 800 g de tomates concassées","1 boîte de 400 g de lentilles dans de l'eau non salée","1 boîte de 400 g de haricots cannellini dans de l'eau non salée","1 c. à soupe de ketchup","coriandre, pour la garniture"],
["Chauffez l'huile dans une grande casserole, ajoutez les oignons et faites cuire 5 à 8 minutes, jusqu'à ce qu'ils commencent à dorer.","Ajoutez le poivron rouge, les carottes, la courgette et les champignons et faites cuire encore 10 minutes.","Ajoutez ensuite le piment en poudre, le cumin, l'origan et les tomates. Mélangez bien, puis laissez cuire encore 10 minutes en remuant régulièrement.","Ajoutez les lentilles et les haricots avec leur eau et le ketchup. Mélangez bien et portez à léger bouillonnement. Couvrez et laissez mijoter doucement 30 minutes en remuant régulièrement."],
["Se conserve au réfrigérateur jusqu'à trois jours, ou se congèle.","Faites attention avec le piment : vous pouvez toujours en ajouter, mais vous ne pouvez pas en enlever ! Ajoutez-en un peu et laissez le temps à la chaleur de se diffuser, goûtez et n'en ajoutez que si nécessaire. Si vous partagez le plat avec des amis, préparez-le doux et servez avec de la sauce pimentée ou des flocons de piment à part, afin que chacun puisse l'épicer à sa guise.",FRZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes et réchauffez jusqu'à ce que le plat soit bien chaud à cœur.",fv(3)]),
R(7856586,"Salade de carottes au cumin et à la coriandre","Une salade savoureuse, idéale avec une part de quiche ou un morceau de poisson ou de poulet grillé.","4","103 g",
["1 c. à café bombée de graines de cumin","2 c. à café de jus de citron","2 c. à café d'huile d'olive extra vierge","½ oignon rouge, très finement émincé","1 bon tour de moulin de poivre noir frais","2 à 3 carottes (300 g)","feuilles de coriandre fraîche, pour servir"],
["Mettez les graines de cumin au creux de votre main et écrasez-les et frottez-les doucement avec le pouce de l'autre main pour libérer les arômes, puis versez-les dans un bol.","Ajoutez le jus de citron, l'huile d'olive, l'oignon et le poivre. Mélangez et réservez.","À l'aide d'un éplucheur, taillez les carottes en fins rubans.","Mélangez les carottes à la vinaigrette et servez parsemé de quelques feuilles de coriandre fraîche."],
["Vous pouvez utiliser des graines de pavot, de sésame ou de carvi à la place des graines de cumin. Ou essayez une huile différente, comme l'huile de sésame grillé ou de noix.","Pour une salade vraiment colorée, cherchez des carottes anciennes qui, en plus de l'orange, peuvent être violettes, blanches ou jaunes.",fv(1)]),
R(7857625,"Taboulé","Cette salade au goût frais est idéale pour l'été.","2","327 g",
["150 g de boulgour","3 c. à soupe de persil frais, haché","3 c. à soupe de menthe fraîche, hachée","125 g de tomates cerises, coupées en quatre","½ concombre, finement haché","1 botte d'oignons nouveaux, finement émincés","zeste et jus d'un demi-citron","2 c. à soupe d'huile d'olive","poivre noir fraîchement moulu"],
["Mettez le boulgour dans un bol et couvrez-le d'eau bouillante. Laissez gonfler 15 à 20 minutes, jusqu'à ce que les grains soient tendres, puis égouttez le liquide restant.","Mélangez tous les autres ingrédients et incorporez-les au boulgour, assaisonnez et servez."],
["Utilisez du quinoa pour une alternative sans gluten.","Vous pouvez ajouter de nombreux ingrédients au taboulé. Essayez des poivrons doux, de l'oignon rouge, de la carotte, du fenouil ou du céleri finement hachés. Utilisez de la ciboulette ou de la coriandre et des légumes rôtis comme la courge butternut, les courgettes et les aubergines. Ou ajoutez des raisins secs, des noix, des graines ou de la grenade.",FRZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes pour servir, ou réchauffez au micro-ondes.",fv(2)]),
R(7859144,"Risotto à la tomate et au poivron rouge","Un risotto simple d'inspiration méditerranéenne.","2","390 g",
["1 c. à soupe d'huile de colza","1 petit oignon, finement haché","100 g de riz à risotto","1 boîte de 400 g de tomates pelées, jus et chair mixés en purée","150 ml de bouillon de légumes pauvre en sel","1 c. à soupe de parmesan frais, râpé","1 boîte de 400 g de piments doux (pimientos), égouttés et chair émincée","poivre noir fraîchement moulu"],
["Chauffez l'huile dans une poêle antiadhésive. Ajoutez l'oignon et faites revenir 2 à 3 minutes, jusqu'à ce qu'il soit ramolli.","Incorporez le riz et enrobez-le d'huile. Versez les tomates et le bouillon, portez à ébullition et laissez mijoter doucement 15 à 20 minutes en remuant sans cesse, jusqu'à ce que le riz soit juste tendre.","Incorporez les autres ingrédients, assaisonnez bien, faites chauffer et servez."],
["Gardez une bouilloire d'eau bouillante à portée de main. Si le risotto commence à attacher, vous pouvez ajouter un filet d'eau. Tant que vous utilisez de l'eau bouillante, cela n'arrêtera pas la cuisson du riz.","Remuer constamment un risotto pendant la cuisson le rend plus crémeux.",FRZ+"peut être congelé une fois cuit. Refroidissez rapidement. Décongelez au réfrigérateur et réchauffez jusqu'à ce que le plat soit bien chaud à cœur. Consommez immédiatement et jetez les restes.",fv(4)]),
R(7859226,"Papillotes de poisson","Ce plat de poisson cuit à la vapeur est une option saine pour un dîner rapide.","1","394 g",
["1 morceau de filet de poisson blanc épais, sans peau (environ 125 g)","1 petit poireau, finement émincé","1 boîte de 215 g de haricots beurre, égouttés et rincés","1 brin de persil, haché","1 c. à soupe de crème fraîche allégée mélangée à 1 c. à soupe de bouillon","poivre noir fraîchement moulu"],
["Préchauffez le four à 200 °C (th. 6).","Découpez un grand carré de papier aluminium d'environ 25 cm x 25 cm.","Placez le poisson, les poireaux, les haricots et le persil au centre du papier aluminium, versez dessus le mélange de crème fraîche et de bouillon, poivrez, puis repliez et fermez en papillote.","Posez sur une plaque de cuisson et faites cuire 15 minutes, jusqu'à ce que le poisson soit opaque et s'effeuille facilement à la fourchette. Ouvrez la papillote et transférez dans une assiette de service. Servez avec un quartier de citron."],
["Vous pouvez utiliser 1 c. à soupe de vin blanc ou de jus de citron à la place du bouillon.","Essayez d'ajouter d'autres légumes, comme des pois mange-tout ou des asperges.","La cuisson à la vapeur en papillote limite la vaisselle et constitue un mode de cuisson sain.",fv(2)]),
R(7860482,"Hachis de dinde aux champignons","Un hachis salé rapide dans une sauce riche.","6","214 g",
["1 c. à café d'huile de tournesol","3 oignons, finement hachés","3 carottes, coupées en petits dés","500 g de hachis de cuisse de dinde","250 g de champignons, émincés","1 branche de céleri, coupée en petits dés","1 c. à soupe bombée de farine ordinaire","1 cube de bouillon de volaille pauvre en sel, dissous dans 500 ml d'eau bouillante","1 bonne pincée de poivre blanc","2 c. à café de sauce soja à teneur réduite en sel"],
["Chauffez l'huile dans une casserole. Ajoutez les oignons et les carottes et faites cuire 4 à 5 minutes, jusqu'à ce que les oignons commencent à dorer.","Ajoutez le hachis de dinde, les champignons et le céleri. Faites cuire 4 à 5 minutes en défaisant les paquets de viande hachée avec une cuillère en bois.","Saupoudrez de farine et mélangez bien pour que le tout soit enrobé. Versez progressivement le bouillon en remuant sans cesse jusqu'à ce que la sauce commence à épaissir.","Ajoutez le poivre et la sauce soja, remuez et réduisez le feu au minimum. Couvrez et laissez mijoter doucement 3 à 4 minutes."],
["Idéal servi avec des légumes à feuilles vertes et des patates douces au four.","Cette recette fonctionne bien avec du hachis de porc, de bœuf ou d'agneau.","Pour une version végétalienne, utilisez une alternative végétale à la viande hachée et un cube de bouillon de légumes.","Pour en faire une tourte pauvre en matières grasses, mettez le hachis dans un plat à tarte, recouvrez de 4 feuilles de pâte filo légèrement badigeonnées de 2 c. à café d'huile de colza et faites cuire 7 à 10 minutes.",FRZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes et réchauffez jusqu'à ce que le plat soit bien chaud à cœur.",fv(2)]),
R(7863056,"Boulettes de thon, sauce tomate","De petites boulettes croustillantes de thon dans une sauce tomate, idéales pour le dîner avec les enfants. Envoyée par Eiri Stephen","2","380 g",
["1 grosse poignée (environ 25 g) d'herbes fraîches mélangées (par ex. persil, menthe, origan, thym et basilic)","1 boîte de 160 g de thon à l'huile de tournesol, égouttée (réservez l'huile)","25 g de pignons de pin","45 g de chapelure complète","zeste d'un citron","1 pincée de sel et de poivre","1 œuf, battu","200 g de coulis de tomate (passata)","2 quartiers de citron, pour servir"],
["Hachez finement les herbes, puis mélangez tous les ingrédients et façonnez 12 boulettes de la taille d'une noix.","Versez l'huile de la boîte de thon dans une poêle et faites dorer les boulettes de thon 10 à 12 minutes en les retournant régulièrement.","Pendant ce temps, faites chauffer le coulis de tomate, ajoutez les boulettes de thon et servez avec un quartier de citron."],
["Si vous n'avez pas d'herbes fraîches, utilisez 2 c. à café d'herbes séchées mélangées.","Vous pouvez ajouter une pincée de flocons de piment ou une gousse d'ail écrasée pour les relever un peu.","Les portions pour les enfants varient selon leur âge et leurs besoins nutritionnels. Les informations nutritionnelles sont basées sur la portion d'un adulte.",fv(1)]),
R(7868675,"Wraps brunch végétariens","Ce plat rapide et savoureux comblera vos envies de brunch.","2","204 g",
["1 spray d'huile de tournesol","4 œufs, battus","1 c. à soupe de","ciboulette fraîche hachée","75 g de fromage frais allégé","2 gros champignons portobello ou de couche","2 c. à café de vinaigre balsamique","2 tomates allongées, épépinées et coupées en petits dés","¼ d'oignon rouge, très finement émincé"],
["Chauffez une petite poêle et vaporisez-la de 2 pressions d'huile. Ajoutez ¼ des œufs battus et inclinez la poêle pour que l'œuf s'étale en un disque de 15 cm. Faites cuire 30 secondes, retournez délicatement et faites cuire encore 30 secondes. Déposez sur une assiette et répétez pour obtenir 4 wraps au total.","Mélangez la ciboulette et le fromage. Mettez les champignons sur une assiette, arrosez chacun de 1 c. à café de vinaigre, couvrez de film alimentaire, percez et faites cuire au micro-ondes à puissance maximale 2 minutes. Émincez finement.","Tartinez les wraps de fromage, disposez les champignons dessus, parsemez de tomates et d'oignon hachés, roulez sans trop serrer et servez. Délicieux chaud ou froid."],
[fv(0)]),
R(7870024,"Poulet à la grecque façon maison","Ce plat grec traditionnel est délicieux servi avec une salade ou des légumes.","4","378 g",
["4 blancs de poulet sans os ni peau (150 g chacun)","500 g de pommes de terre non épluchées, coupées en quartiers","zeste râpé et jus de 2 citrons","1 c. à soupe d'huile d'olive","200 ml de bouillon de volaille","4 gousses d'ail, épluchées","2 c. à soupe de persil frais, haché","poivre noir fraîchement moulu"],
["Préchauffez le four à 200 °C (th. 6).","Placez le poulet dans un plat allant au four et disposez les pommes de terre autour.","Mélangez tous les autres ingrédients, sauf le persil, et versez sur le poulet.","Couvrez de papier aluminium et faites cuire 35 minutes, retirez le papier aluminium et poursuivez la cuisson 15 à 20 minutes.","Parsemez de persil, assaisonnez selon votre goût et servez."],
["Cette recette convient aussi très bien avec des morceaux de viande maigres comme le filet d'agneau ou le filet de porc.","Vous pouvez utiliser des patates douces à la place des pommes de terre ordinaires.","Vous pouvez rendre cette recette encore plus saine en utilisant un bouillon de volaille à teneur réduite en sel.","Servez avec une salade ou des légumes de saison pour vous aider à atteindre vos « 5 par jour ».",FRZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur et réchauffez jusqu'à ce que le plat soit bien chaud à cœur.",fv(0)]),
R(7878991,"Brochettes de poulet marinées et couscous","Ce plat de poulet se marie bien avec un couscous au citron.","2","489 g",
["1 gros blanc de poulet (200 g), coupé en lanières","4 c. à soupe de babeurre","1 c. à café de pesto","1 gousse d'ail, écrasée","1 poivron rouge, coupé en morceaux","2 gros champignons, coupés en tranches épaisses","150 g de semoule de couscous","200 ml de bouillon de volaille bouillant","zeste râpé et jus d'1 citron","1 sachet de 80 g de feuilles de roquette","2 oignons nouveaux, émincés"],
["Mettez le poulet, le babeurre, le pesto et l'ail dans un bol et mélangez bien. Faites tremper les brochettes en bois dans l'eau 15 minutes pour éviter qu'elles ne brûlent.","Laissez mariner 20 minutes. Enfilez le poulet sur les brochettes en alternant avec le poivron et les champignons.","Placez sous un gril chaud et faites griller 6 à 7 minutes en retournant de temps en temps.","Pendant ce temps, mettez la semoule de couscous dans un bol, versez dessus le bouillon, le zeste et le jus de citron. Couvrez le bol de film alimentaire et laissez reposer 5 minutes.","Incorporez les feuilles de roquette et les oignons nouveaux et servez avec les brochettes de poulet."],
["Pour une version encore plus saine, essayez de servir avec du couscous complet.","Délicieux servi froid, il constitue un excellent repas à emporter.","Pour une version au poisson, utilisez des cubes de saumon ou de très grosses crevettes.",fv(1)]),
R(7879167,"Gratin d'aubergines et de courgettes au parmesan","Une version saine d'un gratin italien classique.","4","448 g",
["2 grosses aubergines (environ 700 g), coupées en rondelles de 1 cm","2 grosses courgettes, coupées en lanières de 0,5 cm","1 c. à soupe d'huile d'olive","1 oignon, finement haché","1 poivron rouge, finement haché","2 à 3 gousses d'ail, écrasées","1 c. à café bombée d'origan séché","1 boîte de 400 g de tomates concassées","50 g de parmesan, finement râpé","120 g de mozzarella allégée, finement tranchée"],
["Préchauffez le four à 180 °C (th. 4). Faites griller les aubergines et les courgettes jusqu'à ce qu'elles soient légèrement dorées de chaque côté.","Pendant ce temps, versez l'huile dans une casserole avec l'oignon et remuez de temps en temps pendant 5 minutes. Ajoutez ensuite le poivron rouge en remuant régulièrement pendant encore 5 minutes.","Incorporez l'ail, l'origan et les tomates, et laissez mijoter 5 minutes.","Versez un peu de sauce dans un plat allant au four, couvrez de tranches d'aubergine et de courgette, puis ajoutez de la sauce et saupoudrez de parmesan. Répétez jusqu'à la dernière couche d'aubergine et de courgette, puis terminez avec le reste de la sauce, le parmesan et, enfin, les tranches de mozzarella.","Faites cuire au four 30 à 40 minutes, jusqu'à ce que le dessus soit doré.","Servez avec un tour de moulin de poivre noir, de la salade, des pâtes sans gluten ou de la polenta pour que le plat reste sans gluten."],
["Pour une alternative végétarienne au parmesan, remplacez-le par un fromage à pâte dure de type végétarien.","Vous pouvez assembler ce plat, le réfrigérer et le faire cuire plus tard, ou le lendemain. Vous pouvez même le congeler et le cuire au moment voulu.","Vous pouvez remplacer le parmesan par du Grana Padano, légèrement moins cher et tout aussi bon.",FRZ+"peut être congelé une fois cuit. Congelez en portions. Décongelez au micro-ondes, puis réchauffez au micro-ondes ou couvert de papier aluminium dans un four moyen. Réchauffez jusqu'à ce que le plat soit bien chaud.",fv(3)]),
]
save(4,recs)
